update ui.dashboardquery set vcdashboardquery =
'{
    "Account": {
        "Payer": "select vcpayeeaddr as  \"BeneficiaryIFSC_AccountNo\", cast(observations->>''ts'' as timestamp with time zone ) as \"Txn Date\", observations->''txn''->>''id'' as \"Txn ID\", dobservationamount as \"Txn Amount\", observations->''txn''->''attribs''->>''purpose'' as \"Purpose\", observations->''payee''->''attribs''->>''name'' as \"Baneficiary name\", observations->''txn''->''attribs''->>''beneVPA'' as \"Beneficiary VPA id\", observations->''txn''->''attribs''->>''beneAccNo'' as \"Baneficiary A/c No\", observations->''txn''->''attribs''->>''beneBankName'' as \"Baneficiary Bank Name\", observations->''txn''->''attribs''->>''beneifsc'' as \"Baneficiary Bank IFSC\", observations->''txn''->''attribs''->>''clientName'' as \"Merchant Name\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->''attribs''->>''ecollectAccNo'', observations->''observations''->''payeeVPA''->''account''->''customer''->''attribs''->>''ecollectAccNo'') as \"Merchant A/c No.\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->>''externalId'', observations->''observations''->''payeeVPA''->''account''->''customer''->>''externalId'')  as \"Merchant Id\", observations->''txn''->''attribs''->>''partnerName'' as \"Partner Name\", observations->''txn''->''attribs''->>''transactionType'' as \"Transaction Type\", observations->''txn''->''attribs''->>''field5'' as \"Field 5\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->''attribs''->>''panNo'', observations->''observations''->''payeeVPA''->''account''->''customer''->''attribs''->>''panNo'') as \"PAN Number\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->>''registered_mobile'', observations->''observations''->''payeeVPA''->''account''->''customer''->>''registered_mobile'') as \"Mobile Number\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->>''email'', observations->''observations''->''payeeVPA''->''account''->''customer''->>''email'') as \"Email id\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->''attribs''->>''registeredAddress'', observations->''observations''->''payeeVPA''->''account''->''customer''->''attribs''->>''registeredAddress'') as \"Merchant address\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->''attribs''->>''gstNumber'', observations->''observations''->''payeeVPA''->''account''->''customer''->''attribs''->>''gstNumber'') as \"GSTN\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->''attribs''->>''upperTurnoverSlab'', observations->''observations''->''payeeVPA''->''account''->''customer''->''attribs''->>''upperTurnoverSlab'') as \"Turnover\"  from analytics.trans l where  l.vcpayeraccountexternalid = :VpaAddress  and  dttrxntime between :StartDate  and :EndDate order by dttrxntime desc limit 50000",
        "Payee": "select vcpayeeaddr as  \"BeneficiaryIFSC_AccountNo\", cast(observations->>''ts'' as timestamp with time zone ) as \"Txn Date\", observations->''txn''->>''id'' as \"Txn ID\", dobservationamount as \"Txn Amount\", observations->''txn''->''attribs''->>''purpose'' as \"Purpose\", observations->''payee''->''attribs''->>''name'' as \"Baneficiary name\", observations->''txn''->''attribs''->>''beneVPA'' as \"Beneficiary VPA id\", observations->''txn''->''attribs''->>''beneAccNo'' as \"Baneficiary A/c No\", observations->''txn''->''attribs''->>''beneBankName'' as \"Baneficiary Bank Name\", observations->''txn''->''attribs''->>''beneifsc'' as \"Baneficiary Bank IFSC\", observations->''txn''->''attribs''->>''clientName'' as \"Merchant Name\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->''attribs''->>''ecollectAccNo'', observations->''observations''->''payeeVPA''->''account''->''customer''->''attribs''->>''ecollectAccNo'') as \"Merchant A/c No.\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->>''externalId'', observations->''observations''->''payeeVPA''->''account''->''customer''->>''externalId'')  as \"Merchant Id\", observations->''txn''->''attribs''->>''partnerName'' as \"Partner Name\", observations->''txn''->''attribs''->>''transactionType'' as \"Transaction Type\", observations->''txn''->''attribs''->>''field5'' as \"Field 5\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->''attribs''->>''panNo'', observations->''observations''->''payeeVPA''->''account''->''customer''->''attribs''->>''panNo'') as \"PAN Number\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->>''registered_mobile'', observations->''observations''->''payeeVPA''->''account''->''customer''->>''registered_mobile'') as \"Mobile Number\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->>''email'', observations->''observations''->''payeeVPA''->''account''->''customer''->>''email'') as \"Email id\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->''attribs''->>''registeredAddress'', observations->''observations''->''payeeVPA''->''account''->''customer''->''attribs''->>''registeredAddress'') as \"Merchant address\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->''attribs''->>''gstNumber'', observations->''observations''->''payeeVPA''->''account''->''customer''->''attribs''->>''gstNumber'') as \"GSTN\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->''attribs''->>''upperTurnoverSlab'', observations->''observations''->''payeeVPA''->''account''->''customer''->''attribs''->>''upperTurnoverSlab'') as \"Turnover\"  from analytics.trans l where l.vcpayeeaccountexternalid = :VpaAddress  and dttrxntime between :StartDate and  :EndDate order by dttrxntime desc limit 50000",
        "Both": "select vcpayeeaddr as  \"BeneficiaryIFSC_AccountNo\", cast(observations->>''ts'' as timestamp with time zone ) as \"Txn Date\", observations->''txn''->>''id'' as \"Txn ID\", dobservationamount as \"Txn Amount\", observations->''txn''->''attribs''->>''purpose'' as \"Purpose\", observations->''payee''->''attribs''->>''name'' as \"Baneficiary name\", observations->''txn''->''attribs''->>''beneVPA'' as \"Beneficiary VPA id\", observations->''txn''->''attribs''->>''beneAccNo'' as \"Baneficiary A/c No\", observations->''txn''->''attribs''->>''beneBankName'' as \"Baneficiary Bank Name\", observations->''txn''->''attribs''->>''beneifsc'' as \"Baneficiary Bank IFSC\", observations->''txn''->''attribs''->>''clientName'' as \"Merchant Name\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->''attribs''->>''ecollectAccNo'', observations->''observations''->''payeeVPA''->''account''->''customer''->''attribs''->>''ecollectAccNo'') as \"Merchant A/c No.\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->>''externalId'', observations->''observations''->''payeeVPA''->''account''->''customer''->>''externalId'')  as \"Merchant Id\", observations->''txn''->''attribs''->>''partnerName'' as \"Partner Name\", observations->''txn''->''attribs''->>''transactionType'' as \"Transaction Type\", observations->''txn''->''attribs''->>''field5'' as \"Field 5\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->''attribs''->>''panNo'', observations->''observations''->''payeeVPA''->''account''->''customer''->''attribs''->>''panNo'') as \"PAN Number\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->>''registered_mobile'', observations->''observations''->''payeeVPA''->''account''->''customer''->>''registered_mobile'') as \"Mobile Number\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->>''email'', observations->''observations''->''payeeVPA''->''account''->''customer''->>''email'') as \"Email id\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->''attribs''->>''registeredAddress'', observations->''observations''->''payeeVPA''->''account''->''customer''->''attribs''->>''registeredAddress'') as \"Merchant address\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->''attribs''->>''gstNumber'', observations->''observations''->''payeeVPA''->''account''->''customer''->''attribs''->>''gstNumber'') as \"GSTN\", COALESCE(observations->''observations''->''payerVPA''->''account''->''customer''->''attribs''->>''upperTurnoverSlab'', observations->''observations''->''payeeVPA''->''account''->''customer''->''attribs''->>''upperTurnoverSlab'') as \"Turnover\"  from analytics.trans l where (l.vcpayeraccountexternalid = :VpaAddress or l.vcpayeeaccountexternalid=:VpaAddress ) and  dttrxntime  between :StartDate  and  :EndDate  order by dttrxntime desc limit 50000"
